"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2581],{2581:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-devotion-of-suspect-x.png\\"\\n          title=\\"용의자 X의 헌신\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"재인\\"\\n          publishedDate=\\"2017-08-30\\"\\n          isbn=\\"9788990982704\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n\\n이 작품은 기존 전통 추리소설의 문법인 ```누가 범인인가```의 범인 찾기가 아닌 \'그는 왜 모든 것을 걸고 그녀를 지키려 하는가\' 하는 <mark>왜</mark>와 \'설계한 완벽한 알리바이의 실체는 무엇인가\'인 <mark>어떻게</mark>의 질문으로 전환시킨다.  \\n<br>\\n독자는 탐정과 함께 진실을 추적하는 것이 아니라, 주인공의 편에 서서 그의 계획이 성공하기를 바라게 되는 공범자적 심리를 경험하게 한다.  \\n피해자를 극악무도한 인물로 설정하고, 가해자를 보호받아야 할 존재로 설정하고 묘사하여 독자가 이러한 감정을 들도록 장치를 하였다.  \\n<br>\\n<mark>P≠NP</mark> 문제가 주인공의 범죄철학을 상징적으로 보여준다.  \\n```스스로 생각해서 해답을 이끌어내는 것과, 다른 사람의 답이 옳은지 그른지를 판단하는 것 중 어느 쪽이 더 간단할까?```라는 질문은 이 문제의 핵심을 비유적으로 나타낸다.  \\n<br>\\n역시 작가의 대표작이다."}')}}]);